package com.wedo.backend.poll.controller;
import com.wedo.backend.poll.dto.*; import com.wedo.backend.poll.service.PollService; import com.wedo.backend.security.AuthenticatedUserPrincipal; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class PollController { private final PollService service; public PollController(PollService service){this.service=service;} @PostMapping("/activities/{activityId}/polls") public ResponseEntity<PollResponse> create(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID activityId,@Valid @RequestBody CreatePollRequest r){return ResponseEntity.status(201).body(service.create(activityId,p.userId(),r));} @GetMapping("/activities/{activityId}/polls") public List<PollResponse> list(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID activityId){return service.list(activityId,p.userId());} @GetMapping("/polls/{pollId}") public PollResponse get(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId){return service.get(pollId,p.userId());} @PutMapping("/polls/{pollId}/vote") public PollResponse vote(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId,@Valid @RequestBody VotePollRequest r){return service.vote(pollId,p.userId(),r);} @PostMapping("/polls/{pollId}/options") public ResponseEntity<PollResponse> add(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId,@Valid @RequestBody CreatePollOptionRequest r){return ResponseEntity.status(201).body(service.addOption(pollId,p.userId(),r));} @PatchMapping("/polls/{pollId}/options/{optionId}") public PollResponse updateOption(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId,@PathVariable UUID optionId,@Valid @RequestBody UpdatePollOptionRequest r){return service.updateOption(pollId,optionId,p.userId(),r);} @DeleteMapping("/polls/{pollId}/options/{optionId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteOption(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId,@PathVariable UUID optionId){service.deleteOption(pollId,optionId,p.userId());} @PostMapping("/polls/{pollId}/options/{optionId}/disable") public PollResponse disable(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId,@PathVariable UUID optionId){return service.disableOption(pollId,optionId,p.userId());} @PostMapping("/polls/{pollId}/close") public PollResponse close(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId){return service.close(pollId,p.userId());} @GetMapping("/polls/{pollId}/voters") public List<PollVoterResponse> voters(@AuthenticationPrincipal AuthenticatedUserPrincipal p,@PathVariable UUID pollId){return service.voters(pollId,p.userId());} }
